from pathlib import Path
import re

p=Path('FactionLedgerIQ.user.js')
s=p.read_text()

s=s.replace('// @version      1.0.9','// @version      1.1.0',1)
s=s.replace("const VERSION='1.0.9';","const VERSION='1.1.0';",1)

# Replace Inventory desktop table with mobile-friendly cards.
pattern=r"function inventoryHtml\(\)\{.*?\nfunction rafflesHtml\(\)"
match=re.search(pattern,s,re.S)
if not match:
    raise SystemExit('inventoryHtml block not found')
new_inventory=r'''function inventoryHtml(){const rows=inventoryRows();return `<div class="fliq-section"><div class="fliq-section-title"><span>Add Current / Opening Stock</span><span class="fliq-muted">Optional</span></div><div class="fliq-muted">Add only the personal or faction-owned stock you want LedgerIQ to know about.</div><div class="fliq-row fliq-form-row">${itemSearchField('fliq-open-item','Item name or ID')}<input id="fliq-open-qty" class="fliq-input" type="number" min="1" placeholder="Qty"></div><div class="fliq-row fliq-form-row"><select id="fliq-open-owner" class="fliq-select"><option value="PERSONAL">Personally Owned</option><option value="FACTION">Faction Owned</option></select>${state.settings.displayTracking?'<select id="fliq-open-location" class="fliq-select"><option value="PERSONAL_INVENTORY">Personal Inventory</option><option value="DISPLAY_CASE">Display Case</option></select>':'<input id="fliq-open-location" type="hidden" value="PERSONAL_INVENTORY">'}</div><div class="fliq-actions"><button class="fliq-btn fliq-btn-primary" data-fliq="add-opening">Add Stock</button></div></div><div class="fliq-section"><div class="fliq-section-title"><span>Tracked Inventory</span><span class="fliq-muted">${rows.length} item${rows.length===1?'':'s'}</span></div><div class="fliq-inventory-list">${rows.length?rows.map(r=>`<div class="fliq-inventory-card"><div class="fliq-item-top"><div class="fliq-item-name">${esc(r.itemName)}</div><div class="fliq-inventory-mv">${money(r.mv)}<small> current MV</small></div></div><div class="fliq-inventory-stats"><div><span>Personal</span><b>${r.personal.toLocaleString()}</b></div><div><span>Faction</span><b>${r.faction.toLocaleString()}</b></div>${state.settings.displayTracking?`<div><span>Display P / F</span><b>${r.personalDisplay.toLocaleString()} / ${r.factionDisplay.toLocaleString()}</b></div>`:''}</div></div>`).join(''):'<div class="fliq-muted">No tracked inventory yet.</div>'}</div></div>${state.settings.displayTracking?`<div class="fliq-section"><div class="fliq-section-title"><span>Display Case</span></div><div class="fliq-row fliq-form-row">${itemSearchField('fliq-display-item','Item')}<input id="fliq-display-qty" class="fliq-input" type="number" min="1" placeholder="Qty"></div><div class="fliq-actions"><button class="fliq-btn" data-fliq="display-in">Move To Display</button><button class="fliq-btn" data-fliq="display-out">Move To Personal</button></div></div>`:''}`;}
function rafflesHtml()'''
s=s[:match.start()]+new_inventory+s[match.end():]

# Mobile-first CSS overhaul while retaining Torn-style theme.
style_pattern=r"function installStyles\(\)\{.*?document\.head\.appendChild\(s\);\}"
sm=re.search(style_pattern,s,re.S)
if not sm:
    raise SystemExit('installStyles block not found')
new_styles=r'''function installStyles(){if(document.getElementById(STYLE_ID))return;const s=document.createElement('style');s.id=STYLE_ID;s.textContent=`#${PANEL_ID}{position:fixed;z-index:999999;right:6px;top:52px;width:min(480px,calc(100vw - 12px));max-width:calc(100vw - 12px);max-height:calc(100vh - 60px);max-height:calc(100dvh - 60px);overflow:hidden;border:1px solid rgba(120,120,120,.35);border-radius:12px;background:#f3f3f3;color:#222;box-shadow:0 14px 40px rgba(0,0,0,.35);font:13px/1.35 Arial,sans-serif}#${PANEL_ID}.hidden{display:none}#${PANEL_ID},#${PANEL_ID} *{box-sizing:border-box;min-width:0}#${PANEL_ID} *{max-width:100%}.fliq-head{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:10px 12px;background:#242424;color:#fff;border-bottom:3px solid #d34b4b}.fliq-brand{font-weight:700;font-size:15px;overflow-wrap:anywhere}.fliq-version{font-size:10px;color:#bbb;margin-left:6px;white-space:nowrap}.fliq-close{flex:0 0 auto;border:0;background:transparent;color:#ddd;font-size:22px;line-height:1;cursor:pointer}.fliq-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:4px;padding:6px;background:#ddd;overflow:hidden}.fliq-tab{width:100%;min-height:38px;border:0;border-radius:7px;padding:7px 4px;background:#eee;color:#333;font-weight:700;font-size:12px;white-space:normal;overflow-wrap:anywhere}.fliq-tab.active{background:#d34b4b;color:#fff}.fliq-body{padding:9px;overflow-y:auto;overflow-x:hidden;overscroll-behavior:contain;max-height:calc(100vh - 150px);max-height:calc(100dvh - 150px)}.fliq-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:6px}.fliq-card,.fliq-section{width:100%;background:#fff;border:1px solid #d3d3d3;border-radius:9px;padding:9px;overflow:visible}.fliq-section{margin-top:8px}.fliq-card h3{font-size:10px;line-height:1.15;text-transform:uppercase;color:#777;margin:0 0 4px;overflow-wrap:anywhere}.fliq-big{font-size:17px;font-weight:800;overflow-wrap:anywhere}.fliq-section-title{display:flex;justify-content:space-between;gap:8px;align-items:center;font-weight:800;margin-bottom:8px;overflow-wrap:anywhere}.fliq-muted{color:#777;font-size:11px;overflow-wrap:anywhere;word-break:break-word}.fliq-good{color:#2e7d32}.fliq-bad{color:#b3261e}.fliq-row{display:flex;gap:7px;align-items:center;flex-wrap:wrap;margin:7px 0;width:100%}.fliq-grow{flex:1 1 140px}.fliq-form-row>*{flex:1 1 0}.fliq-item-search-wrap{position:relative;flex:1 1 180px;min-width:0}.fliq-autocomplete{position:absolute;z-index:80;left:0;right:0;top:calc(100% + 3px);max-height:190px;overflow-y:auto;border:1px solid #555;border-radius:7px;background:#222;box-shadow:0 8px 22px rgba(0,0,0,.45)}.fliq-autocomplete:empty{display:none}.fliq-autocomplete-item{display:flex;width:100%;align-items:center;justify-content:space-between;gap:8px;border:0;border-bottom:1px solid #444;background:#2b2b2b;color:#eee;padding:10px;text-align:left;font:inherit}.fliq-autocomplete-item:last-child{border-bottom:0}.fliq-autocomplete-item small{color:#aaa;white-space:nowrap}.fliq-autocomplete-item:active{background:#3a3a3a}.fliq-input,.fliq-select,.fliq-textarea{display:block;width:100%;border:1px solid #bdbdbd;border-radius:7px;background:#fff;color:#222;padding:9px;font:inherit}.fliq-input,.fliq-select{min-height:42px}.fliq-textarea{min-height:108px;resize:vertical}.fliq-btn{border:1px solid #aaa;border-radius:7px;background:#eee;color:#222;padding:9px 11px;font-weight:700;cursor:pointer;white-space:normal;overflow-wrap:anywhere}.fliq-btn-primary{background:#d34b4b;color:#fff;border-color:#b63b3b}.fliq-btn-small{padding:6px 8px;font-size:11px;min-height:34px}.fliq-list,.fliq-inventory-list{display:flex;flex-direction:column;gap:7px}.fliq-list-item,.fliq-inventory-card{width:100%;border:1px solid #ddd;border-radius:8px;padding:9px;background:#fafafa;overflow:hidden;overflow-wrap:anywhere}.fliq-item-top{display:flex;justify-content:space-between;gap:8px;align-items:flex-start}.fliq-item-top>*{min-width:0}.fliq-item-name{font-weight:800;overflow-wrap:anywhere}.fliq-pill{flex:0 0 auto;display:inline-block;border-radius:999px;padding:3px 7px;font-size:10px;font-weight:800;background:#e5e5e5;white-space:nowrap}.fliq-pill.red{background:#f5d5d5;color:#8e2222}.fliq-pill.green{background:#d9efdc;color:#286a30}.fliq-pill.gold{background:#f3e6c7;color:#7b5b15}.fliq-inventory-mv{text-align:right;font-weight:800;white-space:nowrap}.fliq-inventory-mv small{display:block;font-size:9px;color:#888;font-weight:400}.fliq-inventory-stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:5px;margin-top:8px}.fliq-inventory-stats>div{padding:6px;border-radius:6px;background:rgba(127,127,127,.08)}.fliq-inventory-stats span{display:block;font-size:9px;text-transform:uppercase;color:#777}.fliq-inventory-stats b{display:block;font-size:14px;margin-top:1px;overflow-wrap:anywhere}.fliq-table{width:100%;border-collapse:collapse;table-layout:fixed}.fliq-table th,.fliq-table td{padding:6px 4px;border-bottom:1px solid #e4e4e4;text-align:left;vertical-align:top;overflow-wrap:anywhere}.fliq-table th{font-size:10px;color:#777;text-transform:uppercase}.fliq-actions{display:flex;gap:7px;flex-wrap:wrap;margin-top:8px}.fliq-actions .fliq-btn{flex:1 1 140px}#fliq-v1-toast{position:fixed;z-index:1000002;left:50%;bottom:24px;transform:translateX(-50%) translateY(20px);opacity:0;background:#242424;color:#fff;border-radius:8px;padding:9px 13px;transition:.18s;pointer-events:none;max-width:90vw}#fliq-v1-toast.show{opacity:1;transform:translateX(-50%) translateY(0)}#fliq-v1-modal{position:fixed;z-index:1000001;inset:0;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;padding:8px}#fliq-v1-modal .box{width:min(620px,100%);max-width:100%;max-height:92vh;max-height:92dvh;overflow-y:auto;overflow-x:hidden;border-radius:10px;background:#f4f4f4;color:#222;padding:10px;box-shadow:0 16px 50px rgba(0,0,0,.45)}@media(max-width:520px){#${PANEL_ID}{right:5px;top:48px;width:calc(100vw - 10px);max-width:calc(100vw - 10px);max-height:calc(100dvh - 54px);border-radius:10px}.fliq-head{padding:9px 10px}.fliq-brand{font-size:14px}.fliq-tabs{grid-template-columns:repeat(3,minmax(0,1fr));gap:3px;padding:5px}.fliq-tab{min-height:36px;padding:6px 3px;font-size:11px}.fliq-body{padding:7px;max-height:calc(100dvh - 137px)}.fliq-grid{gap:4px}.fliq-card{padding:7px}.fliq-card h3{font-size:8px}.fliq-big{font-size:14px}.fliq-section{padding:8px;margin-top:7px}.fliq-row{display:grid;grid-template-columns:minmax(0,1fr);gap:6px}.fliq-row>*{width:100%!important;max-width:100%!important}.fliq-form-row>*{width:100%!important}.fliq-actions{display:grid;grid-template-columns:minmax(0,1fr);gap:6px}.fliq-actions .fliq-btn{width:100%;min-height:41px}.fliq-item-top{align-items:flex-start}.fliq-inventory-stats{grid-template-columns:repeat(2,minmax(0,1fr))}.fliq-inventory-stats>div:last-child:nth-child(3){grid-column:1/-1}.fliq-textarea{min-height:96px}.fliq-autocomplete{max-height:170px}.fliq-pill{font-size:9px}.fliq-list-item,.fliq-inventory-card{padding:8px}}@media(prefers-color-scheme:dark){#${PANEL_ID}{background:#202020;color:#eee;border-color:#444}.fliq-tabs{background:#181818}.fliq-tab{background:#333;color:#ddd}.fliq-card,.fliq-section{background:#292929;border-color:#444}.fliq-list-item,.fliq-inventory-card{background:#242424;border-color:#444}.fliq-input,.fliq-select,.fliq-textarea{background:#1c1c1c;color:#eee;border-color:#555}.fliq-btn{background:#3a3a3a;color:#eee;border-color:#555}.fliq-table th,.fliq-table td{border-color:#444}.fliq-muted{color:#aaa}.fliq-inventory-stats>div{background:rgba(255,255,255,.05)}.fliq-inventory-stats span{color:#aaa}.fliq-inventory-mv small{color:#aaa}#fliq-v1-modal .box{background:#242424;color:#eee}}`;document.head.appendChild(s);}'''
s=s[:sm.start()]+new_styles+s[sm.end():]

p.write_text(s)
